// Validates the private health-question data (server/health-search/data/)
// and writes server/health-search/dataset.generated.js, the only module the
// search API imports. Run after any data change:
//
//   npm run health-search:data            validate + generate
//   npm run health-search:data -- --check fail if the generated file is stale
//
// The data never goes to dist/ or public/: it is bundled only into the
// serverless function (api/health-search.js).

import { readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { validateDataset } from '../server/health-search/validate.js';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', 'server', 'health-search');
const dataDir = join(root, 'data');
const read = (p) => JSON.parse(readFileSync(p, 'utf8'));

const carriers = read(join(dataDir, 'carriers.json'));
const concepts = read(join(dataDir, 'concepts.json'));
const questionFiles = readdirSync(join(dataDir, 'questions'))
  .filter((f) => f.endsWith('.json'))
  .sort()
  .map((f) => read(join(dataDir, 'questions', f)));

const result = validateDataset({ carriers, questionFiles, concepts });
for (const w of result.warnings) console.warn(`warning: ${w}`);
for (const p of result.pending) console.log(`pending: ${p}`);
if (result.errors.length) {
  for (const e of result.errors) console.error(`error: ${e}`);
  console.error(`\nhealth-search data: ${result.errors.length} error(s); dataset.generated.js not written.`);
  process.exit(1);
}

const stripAbout = (o) => JSON.parse(JSON.stringify(o, (k, v) => (k.startsWith('_') ? undefined : v)));
const dataset = {
  status: result.complete ? 'complete' : 'incomplete',
  counts: result.counts,
  total: result.total,
  carriers: stripAbout(carriers.carriers),
  concepts: stripAbout(concepts.concepts),
  questions: questionFiles.flatMap((f) => f.questions.map((q) => ({ carrierId: f.carrierId, ...q }))),
};
const out = `// GENERATED by scripts/health-search-data.mjs from server/health-search/data/.
// Do not edit by hand. Private: imported only by the serverless search API.
export const dataset = ${JSON.stringify(dataset, null, 1)};
`;
const target = join(root, 'dataset.generated.js');
if (process.argv.includes('--check')) {
  if (!existsSync(target) || readFileSync(target, 'utf8') !== out) {
    console.error('health-search data: dataset.generated.js is out of date. Run `npm run health-search:data`.');
    process.exit(1);
  }
  console.log(`health-search data: up to date (${result.total} questions, status ${dataset.status}).`);
} else {
  writeFileSync(target, out);
  console.log(`health-search data: wrote dataset.generated.js (${result.total} of ${carriers.expectedQuestionTotal} questions, status ${dataset.status}).`);
}
console.log(`counts: ${Object.entries(result.counts).map(([k, v]) => `${k} ${v}`).join(', ')}`);
